item.content:encoded:
.portfolio-filter-button{
    margin-bottom: 40px;
}

.portfolio-filter-button.d-flex button {
    margin-right: 10px;
    background: #000;
    color: #fff;
    padding: 6px 12px;
}

.portfolio-filter-button.d-flex button.active {
    margin-right: 10px;
    background: #f00;
    color: #fff;
    padding: 6px 12px;
}
element.style {
    background-color: rgb(41 42 48 / 0%) !important;
}

/* a.product-add-cart-btn.w-100.w-100.cart-button.button.product_type_simple.add_to_cart_button.ajax_add_to_cart.added {
    display: none;
}

/*  */
.added_to_cart{
    font-weight: 600;
    font-size: 15px;
    color: var(--tp-common-white);
    background-color: var(--tp-common-black);
    display: inline-block;
    padding: 7px 25px;
    text-align: center;
    display: block;
}

.added_to_cart:hover{
    color: var(--tp-common-white);
    background-color: var(--tp-theme-1);
}

.woosc-area {
    background: transparent !important;
}

/* woo rating */
.star-rating{
	position: relative;
	display: inline-block;
}
.star-rating span {
	position: absolute;
	top: 0;
	left: 0;
	overflow: hidden;
	font-size: 0px;
	display: flex;
}
.star-rating::before {
	font-family: "Font Awesome 6 Pro";
	content: "\f005\f005\f005\f005\f005";
	text-transform: uppercase;
	letter-spacing: 3px;
	color: var(--tp-common-yellow-5);
	font-weight: 300;
	font-size: 11px;
}
.star-rating span::before {
	font-family: "Font Awesome 6 Pro";
	content: "\f005\f005\f005\f005\f005";
	text-transform: uppercase;
	letter-spacing: 3px;
	color: var(--tp-common-yellow-5);
	font-weight: 900;
	display: inline-block;
	font-size: 11px;
}

/* filter */

/* filter */
.woocommerce .widget_price_filter .ui-slider-horizontal {
    height: .5em;
}

.woocommerce .widget_price_filter .ui-slider {
    position: relative;
    text-align: left;
    margin-left: .5em;
    margin-right: .5em;
}

.price_slider_amount {
    margin-top: 30px;
    display: flex;
    justify-content: space-between;
}

.woocommerce .widget_price_filter .ui-slider .ui-slider-range {
    position: absolute;
    z-index: 1;
    font-size: .7em;
    display: block;
    border: 0;
    border-radius: 1em;
    background-color: #7f54b3;
}

.woocommerce .widget_price_filter .price_slider_wrapper .ui-widget-content {
    border-radius: 1em;
    background-color: #35224c;
    border: 0;
}

.woocommerce .widget_price_filter .ui-slider .ui-slider-handle {
    position: absolute;
    z-index: 2;
    width: 1em;
    height: 1em;
    background-color: #7f54b3;
    border-radius: 1em;
    cursor: ew-resize;
    outline: 0;
    top: -.3em;
    margin-left: -.5em;
}

.price_slider_amount button.button {
    background: #000;
    color: #fff;
    padding: 4px 13px;
}

.woocommerce .widget_price_filter .ui-slider .ui-slider-range {
    position: absolute;
    z-index: 1;
    font-size: .7em;
    display: block;
    border: 0;
    border-radius: 1em;
    background-color: #7f54b3;
}

.woocommerce .widget_price_filter .ui-slider-horizontal .ui-slider-range {
    top: 0;
    height: 100%;
}

.woocommerce-product-rating {
    display: flex;
}

.product__details-rating-count {
    position: relative;
    margin-bottom: 2px;
    padding-left: 9px;
    margin-left: 4px;
}

.product__details-action .stock.in-stock {
    display: none;
}
.product__details-action .product-action-btn {
    width: 50px;
    height: 50px;
    line-height: 48px;
    text-align: center;
    font-size: 18px;
    color: var(--tp-common-black);
    border: 1px solid #DADCE0;
    margin-right: 6px;
}

.product__details-action button {
    margin-bottom: 0;
}

.product__details-action .cart {
    margin-right: 6px;
}

ol.flex-control-nav.flex-control-thumbs li {
    width: 20%;
    list-style: none;
    padding: 0 5px;
}

ol.flex-control-nav.flex-control-thumbs {
    display: flex;
    flex-wrap: wrap;
    margin: 0 -5px;
    margin-top: 10px;
    padding-left: 0;
}

ol.flex-control-nav.flex-control-thumbs li img {
    width: 100%;
}

.product__details-tab-nav-inner .active a{
border-bottom: 2px solid var(--tp-theme-1);
}

.woocommerce-Reviews .commentlist {
    list-style: none;
    padding: 0;
}

.woocommerce-Reviews img {
    height: 50px;
    width: 50px;
    margin-right: 20px;
    border-radius: 100px;
}
/* details rating */

.woocommerce p.stars a {
    position: relative;
    height: 1em;
    width: 1em;
    text-indent: -999em;
    display: inline-block;
    text-decoration: none;
    font-size: 24px;
}

.woocommerce p.stars a::before {
    display: block;
    position: absolute;
    top: 0;
    left: 0;
    width: 1em;
    height: 1em;
    line-height: 1;
    font-family: "Font Awesome 6 Pro";
    content: "\f005";
    font-weight: 300;
    text-indent: 0;
}

.woocommerce p.stars.selected a.active::before {
    content: "\f005";
    font-weight: 900;
}

.woocommerce p.stars.selected a:not(.active)::before {
    content: "\f005";
    font-weight: 900;
}
.woocommerce p.stars.selected a.active~a::before {
    content: "\f005";
    font-weight: 300;
}

.woocommerce p.stars:hover a::before {
    content: "\f005";
    font-weight: 900;
}

.woocommerce p.stars a:hover~a::before {
    content: "\f005";
    font-weight: 300;

}

#review_form .nice-select {
    display: none;
}

.related_slider_active{
    margin: 0 -10px;
}

.related_slider_active .col {
    padding: 0 10px;
}

table.shop_table.shop_table_responsive.cart.woocommerce-cart-form__contents {
    width: 100%;
    border: 1px solid #ddd;
}

.shop_table tr{
    border: 1px solid #ddd;
}

.shop_table tr td{
    border: 1px solid #ddd;
}

table.shop_table.woocommerce-checkout-review-order-table {
    width: 100%;
}

p.woocommerce-mini-cart__total.total {
    display: flex;
    justify-content: space-between;
    padding: 20px 20px;
}

.woocommerce-mini-cart__buttons{
    margin: 0 20px;
}

.woocommerce-mini-cart__buttons .button.wc-forward {
    display: inline-block;
    font-size: 16px;
    font-weight: 700;
    color: var(--tp-common-white);
    background-color: var(--tp-grey-1);
    text-align: center;
    font-family: var(--tp-ff-space);
    padding: 10px 30px;
    position: relative;
    z-index: 1;
    overflow: hidden;
    letter-spacing: -0.02em;
    width: 100%;
    color: #222;
}

.woocommerce-mini-cart__button .button.wc-forward.checkout{
    border: 1px solid #ddd;
    color: #222;
    background: transparent;
} */

